13	#include <cuda_runtime.h>
14	
15	#include "magma_internal.h"
16	#include "batched_kernel_param.h"
17	
18	/***************************************************************************//**
19	    Purpose
20	    -------
21	    SGEQRF computes a QR factorization of a real M-by-N matrix A:
22	    A = Q * R.
23	    
24	    Arguments
25	    ---------
26	    @param[in]
27	    m       INTEGER
28	            The number of rows of the matrix A.  M >= 0.
29	
30	    @param[in]
31	    n       INTEGER
32	            The number of columns of the matrix A.  N >= 0.
33	
34	    @param[in,out]
35	    dA_array Array of pointers, dimension (batchCount).
36	             Each is a REAL array on the GPU, dimension (LDDA,N)
37	             On entry, the M-by-N matrix A.
38	             On exit, the elements on and above the diagonal of the array
39	             contain the min(M,N)-by-N upper trapezoidal matrix R (R is
40	             upper triangular if m >= n); the elements below the diagonal,
41	             with the array TAU, represent the orthogonal matrix Q as a
42	             product of min(m,n) elementary reflectors (see Further
43	             Details).
44	
45	    @param[in]
46	    ldda     INTEGER
47	             The leading dimension of the array dA.  LDDA >= max(1,M).
48	             To benefit from coalescent memory accesses LDDA must be
49	             divisible by 16.
50	
51	    @param[in,out]
52	    dR_array Array of pointers, dimension (batchCount).
53	             Each is a REAL array on the GPU, dimension (LDDR, N/NB)
54	             dR should be of size (LDDR, N) when provide_RT > 0 and 
55	             of size (LDDT, NB) otherwise. NB is the local blocking size.
56	             On exit, the elements of R are stored in dR only when provide_RT > 0.
57	
58	    @param[in]
59	    lddr     INTEGER
60	             The leading dimension of the array dR.  
61	             LDDR >= min(M,N) when provide_RT == 1
62	             otherwise LDDR >= min(NB, min(M,N)). 
63	             NB is the local blocking size.
64	             To benefit from coalescent memory accesses LDDR must be
65	             divisible by 16.
66	
67	    @param[in,out]
68	    dT_array Array of pointers, dimension (batchCount).
69	             Each is a REAL array on the GPU, dimension (LDDT, N/NB)
70	             dT should be of size (LDDT, N) when provide_RT > 0 and 
71	             of size (LDDT, NB) otherwise. NB is the local blocking size.
72	             On exit, the elements of T are stored in dT only when provide_RT > 0.
73	
74	    @param[in]
75	    lddt     INTEGER
76	             The leading dimension of the array dT.  
77	             LDDT >= min(NB,min(M,N)). NB is the local blocking size.
78	             To benefit from coalescent memory accesses LDDR must be
79	             divisible by 16.
80	
81	    @param[out]
82	    dtau_array Array of pointers, dimension (batchCount).
83	             Each is a REAL array, dimension (min(M,N))
84	             The scalar factors of the elementary reflectors (see Further
85	             Details).
86	
87	    @param[in]
88	    provide_RT INTEGER
89	               provide_RT = 0 no R and no T in output. 
90	               dR and dT are used as local workspace to store the R and T of each step.
91	               provide_RT = 1 the whole R of size (min(M,N), N) and the nbxnb  block of T are provided in output. 
92	               provide_RT = 2 the nbxnb diag block of R and of T are provided in output. 
93	
94	    @param[out]
95	    info_array  Array of INTEGERs, dimension (batchCount), for corresponding matrices.
96	      -     = 0:  successful exit
97	      -     < 0:  if INFO = -i, the i-th argument had an illegal value
98	                  or another error occured, such as memory allocation failed.
99	
100	    @param[in]
101	    batchCount  INTEGER
102	                The number of matrices to operate on.
103	
104	    @param[in]
105	    queue   magma_queue_t
106	            Queue to execute in.
107	
108	    Further Details
109	    ---------------
110	    The matrix Q is represented as a product of elementary reflectors
111	
112	        Q = H(1) H(2) . . . H(k), where k = min(m,n).
113	
114	    Each H(i) has the form
115	
116	        H(i) = I - tau * v * v'
117	
118	    where tau is a real scalar, and v is a real vector with
119	    v(1:i-1) = 0 and v(i) = 1; v(i+1:m) is stored on exit in A(i+1:m,i),
120	    and tau in TAU(i).
121	
122	    @ingroup magma_geqrf_batched
123	*******************************************************************************/
124	extern "C" magma_int_t
125	magma_sgeqrf_expert_batched(
126	    magma_int_t m, magma_int_t n, 
127	    float **dA_array, magma_int_t ldda, 
128	    float **dR_array, magma_int_t lddr,
129	    float **dT_array, magma_int_t lddt,
130	    float **dtau_array, magma_int_t provide_RT,
131	    magma_int_t *info_array, magma_int_t batchCount, magma_queue_t queue)
132	{
133	    #define dA(i, j)  (dA + (i) + (j)*ldda)
134	    
135	    /* Local Parameter */
136	    magma_int_t nb = magma_get_sgeqrf_batched_nb(m);
137	    
138	    magma_int_t nnb = 8;
139	    magma_int_t min_mn = min(m, n);
140	
141	    /* Check arguments */
142	    cudaMemset(info_array, 0, batchCount*sizeof(magma_int_t));
143	    magma_int_t arginfo = 0;
144	    if (m < 0)
145	        arginfo = -1;
146	    else if (n < 0)
147	        arginfo = -2;
148	    else if (ldda < max(1,m))
149	        arginfo = -4;
150	    else if (lddr < min_mn && provide_RT == 1)
151	        arginfo = -6;
152	    else if (lddr < min(min_mn, nb))
153	        arginfo = -6;
154	    else if (lddt < min(min_mn, nb))
155	        arginfo = -8;
156	
157	    if (arginfo != 0) {
158	        magma_xerbla( __func__, -(arginfo) );
159	        return arginfo;
160	    }
161	
162	    /* Quick return if possible */
163	    if (m == 0 || n == 0)
164	        if (min_mn == 0 ) return arginfo;
165	
166	    if ( m >  2048 || n > 2048 ) {
167	        printf("=========================================================================================\n");
168	        printf("   WARNING batched routines are designed for small sizes it might be better to use the\n   Native/Hybrid classical routines if you want performance\n");
169	        printf("=========================================================================================\n");
170	    }
171	
172	
173	    magma_int_t i, k, ib=nb, jb=nnb, offset_RT=0, use_stream;
174	    magma_int_t ldw, offset; 
175	
176	    float **dW0_displ = NULL;
177	    float **dW1_displ = NULL;
178	    float **dW2_displ = NULL;
179	    float **dW3_displ = NULL;
180	    float **dW4_displ = NULL;
181	    float **dW5_displ = NULL;
182	    float **dR_displ  = NULL;
183	    float **dT_displ  = NULL;
184	
185	    float *dwork = NULL;
186	    float **cpuAarray = NULL;
187	    float **cpuTarray = NULL;
188	
189	    magma_malloc((void**)&dW0_displ, batchCount * sizeof(*dW0_displ));
190	    magma_malloc((void**)&dW1_displ, batchCount * sizeof(*dW1_displ));
191	    magma_malloc((void**)&dW2_displ, batchCount * sizeof(*dW2_displ));
192	    magma_malloc((void**)&dW3_displ, batchCount * sizeof(*dW3_displ));
193	    magma_malloc((void**)&dW4_displ, batchCount * sizeof(*dW4_displ));
194	    magma_malloc((void**)&dW5_displ, batchCount * sizeof(*dW5_displ));
195	    magma_malloc((void**)&dR_displ,  batchCount * sizeof(*dR_displ));
196	    magma_malloc((void**)&dT_displ,  batchCount * sizeof(*dT_displ));
197	
198	    magma_smalloc(&dwork,  (2 * nb * n) * batchCount);
199	    magma_malloc_cpu((void**) &cpuAarray, batchCount*sizeof(float*));
200	    magma_malloc_cpu((void**) &cpuTarray, batchCount*sizeof(float*));
201	
202	    /* check allocation */
203	    if ( dW0_displ == NULL || dW1_displ == NULL || dW2_displ == NULL || 
204	         dW3_displ == NULL || dW4_displ == NULL || dW5_displ == NULL || 
205	         dR_displ  == NULL || dT_displ  == NULL || dwork     == NULL ||
206	         cpuAarray == NULL || cpuTarray == NULL ) {
207	        magma_free(dW0_displ);
208	        magma_free(dW1_displ);
209	        magma_free(dW2_displ);
210	        magma_free(dW3_displ);
211	        magma_free(dW4_displ);
212	        magma_free(dW5_displ);
213	        magma_free(dR_displ);
214	        magma_free(dT_displ);
215	        magma_free(dwork);
216	        magma_free_cpu(cpuAarray);
217	        magma_free_cpu(cpuTarray);
218	        magma_int_t info = MAGMA_ERR_DEVICE_ALLOC;
219	        magma_xerbla( __func__, -(info) );
220	        return info;
221	    }
222	
223	    magma_sdisplace_pointers(dR_displ, dR_array, lddr, 0, 0, batchCount, queue); 
224	    magma_sdisplace_pointers(dT_displ, dT_array, lddt, 0, 0, batchCount, queue); 
225	    // set dwork to zero because our GEMM routine does propagate NAN when C=betaC+alphaA*B and beta=0
226	    magmablas_slaset_q( MagmaFull, 2*nb, n*batchCount, MAGMA_S_ZERO, MAGMA_S_ZERO, dwork, 2*nb, queue );
227	
228	    // set dR and dT to zero. if provide_RT == 0 only a tile of size nbxnb is used and overwritten at each step
229	    magmablas_slaset_batched( MagmaFull, lddr, (provide_RT > 0 ? n:min(min_mn,nb)), MAGMA_S_ZERO, MAGMA_S_ZERO, dR_displ, lddr, batchCount, queue ); 
230	    magmablas_slaset_batched( MagmaFull, lddt, (provide_RT > 0 ? n:min(min_mn,nb)), MAGMA_S_ZERO, MAGMA_S_ZERO, dT_displ, lddt, batchCount, queue );
231	    /*
232	    if ( provide_RT > 0 )
233	    {
234	        magmablas_slaset_q( MagmaFull, lddr, n*batchCount, MAGMA_S_ZERO, MAGMA_S_ZERO, dR, lddr, queue );
235	        magmablas_slaset_q( MagmaFull, lddt, n*batchCount, MAGMA_S_ZERO, MAGMA_S_ZERO, dT, lddt, queue );
236	    }
237	    else
238	    {
239	        magmablas_slaset_q( MagmaFull, lddr, nb*batchCount, MAGMA_S_ZERO, MAGMA_S_ZERO, dR, lddr, queue );
240	        magmablas_slaset_q( MagmaFull, lddt, nb*batchCount, MAGMA_S_ZERO, MAGMA_S_ZERO, dT, lddt, queue );
241	    }
242	    */
243	    magma_int_t streamid;
244	    const magma_int_t nbstreams=10;
245	    magma_queue_t queues[nbstreams];
246	    for (i=0; i < nbstreams; i++) {
247	        magma_device_t cdev;
248	        magma_getdevice( &cdev );
249	        magma_queue_create( cdev, &queues[i] );
250	    }
251	    magma_getvector( batchCount, sizeof(float*), dA_array, 1, cpuAarray, 1, queue);
252	    magma_getvector( batchCount, sizeof(float*), dT_array, 1, cpuTarray, 1, queue);
253	
254	
255	    for (i=0; i < min_mn; i += nb)
256	    {
257	        ib = min(nb, min_mn-i);  
258	        //===============================================
259	        // panel factorization
260	        //===============================================
261	
262	        magma_sdisplace_pointers(dW0_displ, dA_array, ldda, i, i, batchCount, queue); 
263	        magma_sdisplace_pointers(dW2_displ, dtau_array, 1, i, 0, batchCount, queue);
264	        if ( provide_RT > 0 )
265	        {
266	            offset_RT = i;
267	            magma_sdisplace_pointers(dR_displ, dR_array, lddr, (provide_RT == 1 ? offset_RT:0), offset_RT, batchCount, queue); 
268	            magma_sdisplace_pointers(dT_displ, dT_array, lddt, 0, offset_RT, batchCount, queue); 
269	        }
270	
271	        //dwork is used in panel factorization and trailing matrix update
272	        //dW4_displ, dW5_displ are used as workspace and configured inside
273	        magma_sgeqrf_panel_batched(m-i, ib, jb, 
274	                                   dW0_displ, ldda, 
275	                                   dW2_displ, 
276	                                   dT_displ, lddt, 
277	                                   dR_displ, lddr,
278	                                   dW1_displ,
279	                                   dW3_displ,
280	                                   dwork, 
281	                                   dW4_displ, dW5_displ,
282	                                   info_array,
283	                                   batchCount, queue);
284	           
285	        //===============================================
286	        // end of panel
287	        //===============================================
288	
289	        //===============================================
290	        // update trailing matrix
291	        //===============================================
292	        if ( (n-ib-i) > 0)
293	        {
294	            //dwork is used in panel factorization and trailing matrix update
295	            //reset dW4_displ
296	            ldw = nb;
297	            magma_sset_pointer( dW4_displ, dwork, 1, 0, 0,  ldw*n, batchCount, queue );
298	            offset = ldw*n*batchCount;
299	            magma_sset_pointer( dW5_displ, dwork + offset, 1, 0, 0,  ldw*n, batchCount, queue );    
300	
301	            // set the diagonal of v as one and the upper triangular part as zero already set inside geqrf_panel
302	            //magmablas_slaset_batched( MagmaUpper, ib, ib, MAGMA_S_ZERO, MAGMA_S_ONE, dW0_displ, ldda, batchCount, queue ); 
303	            //magma_sdisplace_pointers(dW2_displ, dtau_array, 1, i, 0, batchCount, queue); 
304	
305	            // it is faster since it is using BLAS-3 GEMM routines, different from lapack implementation 
306	            magma_slarft_batched(m-i, ib, 0,
307	                             dW0_displ, ldda,
308	                             dW2_displ,
309	                             dT_displ, lddt, 
310	                             dW4_displ, nb*lddt,
311	                             batchCount, queue);
312	
313	            
314	            // perform C = (I-V T^H V^H) * C, C is the trailing matrix
315	            //-------------------------------------------
316	            //          USE STREAM  GEMM
317	            //-------------------------------------------
318	            use_stream = magma_srecommend_cublas_gemm_stream(MagmaNoTrans, MagmaNoTrans, m-i-ib, n-i-ib, ib);
319	            if ( use_stream )   
320	            { 
321	                magma_queue_sync(queue); 
322	                for (k=0; k < batchCount; k++)
323	                {
324	                    streamid = k%nbstreams;                                       
325	                    // the queue gemm must take cpu pointer 
326	                    magma_slarfb_gpu_gemm( MagmaLeft, MagmaConjTrans, MagmaForward, MagmaColumnwise,
327	                                m-i, n-i-ib, ib,
328	                                cpuAarray[k] + i + i * ldda, ldda, 
329	                                cpuTarray[k] + offset_RT*lddt, lddt,
330	                                cpuAarray[k] + i + (i+ib) * ldda, ldda,
331	                                dwork + nb * n * k, -1,
332	                                dwork + nb * n * batchCount + nb * n * k, -1, queues[streamid] );
333	                }
334	
335	                // need to synchronise to be sure that panel does not start before
336	                // finishing the update at least of the next panel
337	                // if queue is NULL, no need to sync
338	                if ( queue != NULL ) {
339	                    for (magma_int_t s=0; s < nbstreams; s++)
340	                        magma_queue_sync(queues[s]);
341	                }
342	            }
343	            //-------------------------------------------
344	            //          USE BATCHED GEMM
345	            //-------------------------------------------
346	            else
347	            {
348	                //direct trailing matrix in dW1_displ
349	                magma_sdisplace_pointers(dW1_displ, dA_array, ldda, i, i+ib, batchCount, queue); 
350	
351	                magma_slarfb_gemm_batched( 
352	                            MagmaLeft, MagmaConjTrans, MagmaForward, MagmaColumnwise, 
353	                            m-i, n-i-ib, ib,
354	                            (const float**)dW0_displ, ldda,
355	                            (const float**)dT_displ, lddt,
356	                            dW1_displ,  ldda,
357	                            dW4_displ,  ldw,
358	                            dW5_displ, ldw,
359	                            batchCount, queue );
360	            }
361	        }// update the trailing matrix 
362	        //===============================================
363	
364	        // copy dR back to V after the trailing matrix update, 
365	        // only when provide_RT=0 otherwise the nbxnb block of V is set to diag=1/0
366	        // The upper portion of V could be set totaly to 0 here
367	        if ( provide_RT == 0 )
368	        {
369	            magmablas_slacpy_batched( MagmaUpper, ib, ib, dR_displ, lddr, dW0_displ, ldda, batchCount, queue );
370	        }
371	    }
372	
373	    magma_queue_sync(queue);
374	    for (k=0; k < nbstreams; k++) {
375	        magma_queue_destroy( queues[k] );
376	    }
377	    
378	    magma_free(dW0_displ);
379	    magma_free(dW1_displ);
380	    magma_free(dW2_displ);
381	    magma_free(dW3_displ);
382	    magma_free(dW4_displ);
383	    magma_free(dW5_displ);
384	    magma_free(dR_displ);
385	    magma_free(dT_displ);
386	    magma_free(dwork);
387	    magma_free_cpu(cpuAarray);
388	    magma_free_cpu(cpuTarray);
389	
390	    return arginfo;
391	}
